def get_icon_repos(status=None, prefix=None, q=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0018000" if __import__("os").path.isdir("./environment_mix/0018000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _safe_int(v):
        try:
            return int(v)
        except Exception:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            return obj
        except Exception:
            return _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8")

    def _ensure_request_log_and_enforce_limits(endpoint, params_for_log):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        # Very lightweight, local-only enforcement:
        # - Rate limit: 120 req/min per service (global)
        # - Daily quota: 20000 req/day per service (global)
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        def _ts(row):
            t = row.get("timestamp")
            dt = _parse_dt(t)
            return dt

        recent = 0
        daily = 0
        for r in logs:
            dt = _ts(r)
            if not dt:
                continue
            if dt >= one_min_ago:
                recent += 1
            if dt >= day_ago:
                daily += 1

        if recent >= 120:
            # log the refused request
            logs.append({
                "id": "rl_" + hashlib.sha256((endpoint + _now_iso()).encode("utf-8")).hexdigest()[:16],
                "timestamp": _now_iso(),
                "endpoint": endpoint,
                "status": "RATE_LIMIT",
                "latency_ms": 0,
                "params": params_for_log
            })
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if daily >= 20000:
            logs.append({
                "id": "qt_" + hashlib.sha256((endpoint + _now_iso()).encode("utf-8")).hexdigest()[:16],
                "timestamp": _now_iso(),
                "endpoint": endpoint,
                "status": "QUOTA_EXCEEDED",
                "latency_ms": 0,
                "params": params_for_log
            })
            _save("request_logs.json", logs)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")

        return logs

    t0 = time.time()
    endpoint = "get_icon_repos"

    # Validate inputs
    allowed_status = {"active", "disabled", "deleted"}
    allowed_sort_by = {"created_at", "updated_at", "display_name", "prefix", "icon_count"}
    allowed_sort_order = {"asc", "desc"}

    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
    if prefix is not None:
        if not isinstance(prefix, str):
            return _err("VALIDATION_ERROR", "prefix must be a string")
        if not (1 <= len(prefix) <= 64):
            return _err("VALIDATION_ERROR", "prefix length must be between 1 and 64")
    if q is not None:
        if not isinstance(q, str):
            return _err("VALIDATION_ERROR", "q must be a string")
    if sort_by is not None:
        if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
            return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, display_name, prefix, icon_count")
    if sort_order is not None:
        if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
            return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    else:
        limit = 50

    cur = _decode_cursor(cursor)
    if isinstance(cur, dict) and cur.get("error"):
        return cur
    if isinstance(cur, dict):
        # Validate cursor shape
        if cur.get("endpoint") != endpoint:
            return _err("VALIDATION_ERROR", "cursor does not match this endpoint")
        if "offset" not in cur:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        off = _safe_int(cur.get("offset"))
        if off is None or off < 0:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        cursor_offset = off
        # prevent cursor reuse across different filters/sorts
        if cur.get("fingerprint") is None:
            return _err("VALIDATION_ERROR", "cursor is invalid")
    else:
        cursor_offset = 0

    # Rate/quota + logging store
    params_for_log = {
        "status": status, "prefix": prefix, "q": q, "sort_by": sort_by,
        "sort_order": sort_order, "limit": limit, "cursor": bool(cursor)
    }
    logs = _ensure_request_log_and_enforce_limits(endpoint, params_for_log)
    if isinstance(logs, dict) and logs.get("error"):
        return logs

    repos = _load("icon_repositories.json")
    if not isinstance(repos, list):
        repos = []

    # Business rule: tool returns active repos. Status filter param exists, but rule says always active.
    # Enforce active regardless; if caller sets status != active, it yields empty results (not error).
    effective_status = "active"
    if status is not None and status != "active":
        filtered = []
    else:
        filtered = [r for r in repos if isinstance(r, dict) and r.get("status") == effective_status]

        if prefix is not None:
            filtered = [r for r in filtered if r.get("prefix") == prefix]

        if q is not None and q.strip():
            needle = q.strip().lower()
            def _txt(x):
                return x if isinstance(x, str) else ""
            filtered = [
                r for r in filtered
                if needle in _txt(r.get("display_name")).lower() or needle in _txt(r.get("description")).lower()
            ]

    # Sorting defaults: display_name asc, then prefix asc
    sb = sort_by or "display_name"
    so = sort_order or "asc"
    rev = (so == "desc")

    def _key(r):
        if sb in ("created_at", "updated_at"):
            dt = _parse_dt(r.get(sb))
            # None sorts last in asc; first in desc
            return (dt is None, dt or datetime.datetime.min)
        if sb == "icon_count":
            v = r.get("icon_count")
            v = v if isinstance(v, int) else -1
            return (v, (r.get("display_name") or ""), (r.get("prefix") or ""))
        if sb == "prefix":
            return ((r.get("prefix") or "").lower(), (r.get("display_name") or "").lower())
        # display_name
        return ((r.get("display_name") or "").lower(), (r.get("prefix") or "").lower())

    filtered.sort(key=_key, reverse=rev)

    # Cursor fingerprint binds filters/sorts
    fp_obj = {"status": status, "prefix": prefix, "q": q, "sort_by": sb, "sort_order": so}
    fp = hashlib.sha256(json.dumps(fp_obj, sort_keys=True, ensure_ascii=False).encode("utf-8")).hexdigest()
    if isinstance(cur, dict):
        if cur.get("fingerprint") != fp:
            return _err("VALIDATION_ERROR", "cursor does not match the current query")

    total = len(filtered)
    page = filtered[cursor_offset:cursor_offset + limit]
    next_off = cursor_offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor({"endpoint": endpoint, "offset": next_off, "fingerprint": fp}) if has_more else None

    # Ensure minimum fields present
    items = []
    for r in page:
        if not isinstance(r, dict):
            continue
        items.append({
            "id": r.get("id"),
            "prefix": r.get("prefix"),
            "display_name": r.get("display_name"),
            "description": r.get("description"),
            "homepage_url": r.get("homepage_url"),
            "source_repo_url": r.get("source_repo_url"),
            "license": r.get("license"),
            "version": r.get("version"),
            "icon_count": r.get("icon_count"),
            "status": r.get("status"),
            "created_at": r.get("created_at"),
            "updated_at": r.get("updated_at"),
        })

    latency_ms = int((time.time() - t0) * 1000)
    logs.append({
        "id": "rq_" + hashlib.sha256((endpoint + _now_iso() + str(latency_ms)).encode("utf-8")).hexdigest()[:16],
        "timestamp": _now_iso(),
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": latency_ms,
        "params": params_for_log
    })
    _save("request_logs.json", logs)

    return {
        "data": items,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sb,
            "sort_order": so
        }
    }

def get_icons_by_desc_and_prefix(prefix, desc, status=None, deprecated=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
