            "repo_id": ic.get("repo_id"),
            "prefix": ic.get("prefix"),
            "name": ic.get("name"),
            "description": ic.get("description"),
            "tags": ic.get("tags"),
            "categories": ic.get("categories"),
            "deprecated": ic.get("deprecated"),
            "popularity_score": ic.get("popularity_score"),
