def get_icon_detail_by_prefix_and_name(prefix, name, include_svg=None, asset_type=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0018000" if __import__("os").path.isdir("./environment_mix/0018000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_icon_detail_by_prefix_and_name"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str) and v.strip():
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _find_log_file():
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_logs.json", "usage.json", "rate_limit_events.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    LOG_FILE = _find_log_file()

    def _load_logs():
        logs = _load(LOG_FILE)
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save(LOG_FILE, logs)

    def _check_limits(logs):
        # Conservative default limits (service-like dynamics), per whole service.
        # 120 req/min, 50k req/day
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            dt = _parse_dt(r.get("timestamp")) or _parse_dt(r.get("created_at")) or _parse_dt(r.get("ts"))
            if not dt:
                continue
            if dt >= one_min_ago:
                per_min += 1
            if dt >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load_logs()
        # best-effort limit enforcement: check before writing the current request row
        lim = _check_limits(logs)
        if lim is not None and status == "ok":
            # if we were about to return ok but actually over limit, record as limited
            status = "error"
            error_code = lim["error"]["code"]

        row = {
            "id": "pka_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if credential_id is not None:
            row["credential_id"] = credential_id
        if error_code is not None:
            row["error_code"] = error_code
        logs.append(row)
        _save_logs(logs)
        return lim

    # Validate
    if not isinstance(prefix, str) or not (1 <= len(prefix.strip()) <= 64):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid prefix", field="prefix", rule="prefix length between 1 and 64")
    if not isinstance(name, str) or not (1 <= len(name.strip()) <= 128):
