        if ic.get("status") != "active":
            continue
        if ic.get("repo_id") != repo.get("id"):
            # if prefix+name matches but repo_id isn't the active repo for prefix, treat as not visible
            continue
        matches.append(ic)

    if len(matches) == 0:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Icon not found")
    if len(matches) > 1:
        _log("error", error_code="CONFLICT")
