                break
        if asset is None:
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Icon asset not found for requested type", asset_type="svg")

        asset_out = {k: v for k, v in asset.items()}
        # include svg_body (requested); keep other metadata too
        out["asset"] = asset_out

    _log("ok")
    return {"data": out}

