        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_log_and_enforce_limits(endpoint, params_for_log):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)

        recent = 0
        daily = 0
        for r in logs:
            dt = _parse_dt(r.get("timestamp"))
            if not dt:
                continue
            if dt >= one_min_ago:
                recent += 1
            if dt >= day_ago:
                daily += 1

        if recent >= 120:
            logs.append({
                "id": "rl_" + hashlib.sha256((endpoint + _now_iso()).encode("utf-8")).hexdigest()[:16],
                "timestamp": _now_iso(),
                "endpoint": endpoint,
                "status": "RATE_LIMIT",
                "latency_ms": 0,
                "params": params_for_log
            })
            _save("request_logs.json", logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
