    _log("ok")
    return {"data": {"repository": repo}}

def update_icon_repository(id, display_name=None, description=None, homepage_url=None, source_repo_url=None, license=None, version=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0018000" if __import__("os").path.isdir("./environment_mix/0018000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_icon_repository"

    def _log(status_code, message=None):
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        entry = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        logs.append(entry)
        _save("request_logs.json", logs)

    if not isinstance(id, str):
        _log("VALIDATION_ERROR", "id must be a string")
        return _err("VALIDATION_ERROR", "id must be a string")
    if not (1 <= len(id.strip()) <= 256):
        _log("VALIDATION_ERROR", "malformed id")
        return _err("VALIDATION_ERROR", "malformed id")

    def _opt_str(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            raise ValueError(f"{field} must be a string")
        return v

    try:
        display_name = _opt_str(display_name, "display_name")
        description = _opt_str(description, "description")
        homepage_url = _opt_str(homepage_url, "homepage_url")
        source_repo_url = _opt_str(source_repo_url, "source_repo_url")
        license = _opt_str(license, "license")
        version = _opt_str(version, "version")
    except ValueError as e:
        _log("VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", "status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "disabled", "deleted"):
            _log("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    repos = _load("icon_repositories.json")
    icons = _load("icons.json")

    idx = None
    repo = None
    for i, r in enumerate(repos):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            repo = r
            break
    if repo is None:
        _log("NOT_FOUND", "repository not found")
        return _err("NOT_FOUND", "repository not found")

    # Apply metadata updates
    changed = False
    if display_name is not None:
        dn = display_name.strip()
        if dn == "":
            _log("VALIDATION_ERROR", "display_name cannot be empty")
            return _err("VALIDATION_ERROR", "display_name cannot be empty")
        if dn != repo.get("display_name"):
            repo["display_name"] = dn
            changed = True
    if description is not None and description != repo.get("description"):
        repo["description"] = description
        changed = True
    if homepage_url is not None and homepage_url != repo.get("homepage_url"):
        repo["homepage_url"] = homepage_url
        changed = True
    if source_repo_url is not None and source_repo_url != repo.get("source_repo_url"):
        repo["source_repo_url"] = source_repo_url
        changed = True
    if license is not None and license != repo.get("license"):
        repo["license"] = license
        changed = True
    if version is not None and version != repo.get("version"):
        repo["version"] = version
        changed = True

    # Lifecycle transitions
    if status is not None:
        current = repo.get("status")
        if current not in ("active", "disabled", "deleted"):
            _log("CONFLICT", "repository has invalid status")
            return _err("CONFLICT", "repository has invalid status")

        allowed = {
            "active": {"disabled", "deleted"},
            "disabled": {"active", "deleted"},
            "deleted": set(),
        }
        if status != current:
            if status not in allowed.get(current, set()):
                _log("INVALID_TRANSITION", "invalid status transition")
                return _err("INVALID_TRANSITION", "invalid status transition", from_status=current, to_status=status)

            # Deletion restrict: cannot delete if non-deleted icons reference it
            if status == "deleted":
                for ic in icons:
                    if isinstance(ic, dict) and ic.get("repo_id") == repo.get("id") and ic.get("status") != "deleted":
                        _log("CONFLICT", "cannot delete repository while non-deleted icons reference it")
                        return _err(
                            "CONFLICT",
                            "cannot delete repository while non-deleted icons reference it",
                            rule="delete_restrict",
                            repo_id=repo.get("id"),
                        )

            repo["status"] = status
            changed = True

    if not changed:
        # No success without effect: treat as not found / no-op not allowed for mutation
        _log("NOT_FOUND", "no changes applied")
        return _err("NOT_FOUND", "no changes applied")

    # Maintain constraints
    if not isinstance(repo.get("prefix"), str) or not (1 <= len(repo.get("prefix").strip()) <= 64):
        _log("CONFLICT", "prefix constraint violated")
        return _err("CONFLICT", "prefix constraint violated")
    if not isinstance(repo.get("icon_count"), int) or repo.get("icon_count") < 0:
        _log("CONFLICT", "icon_count constraint violated")
        return _err("CONFLICT", "icon_count constraint violated")

    repo["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    repos[idx] = repo
    _save("icon_repositories.json", repos)

    _log("ok")
    return {"repository": repo}

def get_auth_context(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0018000" if __import__("os").path.isdir("./environment_mix/0018000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "get_auth_context"
    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if isinstance(v, str) and v.strip():
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _find_log_file():
        for fn in ("request_logs.json", "requests.json", "api_requests.json", "audit_logs.json", "usage_logs.json", "usage.json", "rate_limit_events.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return "request_logs.json"

    LOG_FILE = _find_log_file()

    def _load_logs():
        logs = _load(LOG_FILE)
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save(LOG_FILE, logs)

    def _check_limits(logs, marker=None):
        # Per-credential if marker present
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if marker is not None:
                if r.get("credential_id") != marker and r.get("api_key") != marker and r.get("credential") != marker:
                    continue
            dt = _parse_dt(r.get("timestamp")) or _parse_dt(r.get("created_at")) or _parse_dt(r.get("ts"))
            if not dt:
                continue
            if dt >= one_min_ago:
                per_min += 1
            if dt >= day_ago:
                per_day += 1
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if per_day >= 50000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    def _log(status, credential_id=None, error_code=None):
        logs = _load_logs()
        row = {
            "id": "pka_req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if credential_id is not None:
            row["credential_id"] = credential_id
            row["api_key"] = credential_id
        if error_code is not None:
            row["error_code"] = error_code
        logs.append(row)
        _save_logs(logs)

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key is required", field="api_key")
    api_key = api_key.strip()

    # Attempt to authenticate against any plausible credential collection.
    # IMPORTANT: match against client-visible value or id, NOT hashes.
    cred_files = [
        "api_keys.json",
        "credentials.json",
        "auth_credentials.json",
        "keys.json",
        "access_keys.json",
    ]

    credential = None
    cred_file_used = None
    for fn in cred_files:
        path = os.path.join(_DB, fn)
        if not os.path.exists(path):
            continue
        rows = _load(fn)
        if not isinstance(rows, list):
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            # accept by id or common plaintext fields
            if api_key == r.get("id") or api_key == r.get("api_key") or api_key == r.get("key") or api_key == r.get("value") or api_key == r.get("token"):
                # require active-ish if field exists
                st = r.get("status")
                if st is not None and st not in ("active", "enabled", "valid"):
                    continue
                credential = r
                cred_file_used = fn
                break
        if credential is not None:
            break

    # If none found in explicit credential stores, allow repo/icon ids were mistakenly passed previously:
    # but get_auth_context requires a credential; do not treat arbitrary ids as auth.
    if credential is None:
        # Still log the call
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unauthenticated: no valid credential provided.")

    logs = _load_logs()
    marker = credential.get("id") or api_key
    lim = _check_limits(logs, marker=marker)
    if lim is not None:
        _log("error", credential_id=marker, error_code=lim["error"]["code"])
        return lim

    # Build context (best-effort: different stores have different shapes)
    scopes = credential.get("scopes")
    if scopes is None:
        scopes = credential.get("scope")
    if isinstance(scopes, str):
        scopes = [s for s in scopes.replace(",", " ").split() if s]
    if scopes is None:
        scopes = []

    subject = credential.get("subject") or credential.get("account_id") or credential.get("user_id") or credential.get("workspace_id") or credential.get("id")

    # Consumption snapshot from logs
    now = datetime.datetime.utcnow()
    one_min_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)
    used_min = 0
    used_day = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("credential_id") != marker and r.get("api_key") != marker:
            continue
        dt = _parse_dt(r.get("timestamp")) or _parse_dt(r.get("created_at")) or _parse_dt(r.get("ts"))
        if not dt:
            continue
        if dt >= one_min_ago:
            used_min += 1
        if dt >= day_ago:
            used_day += 1

    ctx = {
        "credential": {
            "id": credential.get("id"),
            "type": credential.get("type") or "api_key",
            "status": credential.get("status") or "active",
            "scopes": scopes,
            "store": cred_file_used,
        },
        "subject": subject,
        "rate_limit": {"limit_per_minute": 120, "used_last_minute": used_min},
        "quota": {"limit_per_day": 50000, "used_last_day": used_day},
    }

    _log("ok", credential_id=marker)
    return {"data": ctx}
